Dataspatium.assets.register("presets/api/lantmateriet-stac.api.json","text","{\n \"format\": \"dataspatium-api/1\",\n \"id\": \"lantmateriet-stac\",\n \"name\": \"Lantmäteriet geodata med nyckel (STAC)\",\n \"publisher\": \"Lantmäteriet\",\n \"description\": \"Lantmäteriets fyra STAC-kataloger: vektordata (byggnader, marktäcke, ortnamn, fastighetsindelning, adresser), ortofoton, höjddata (markhöjdmodellen och laserdata) och kartor. Sök filer inom ett område och hämta dem med nyckeln från Geotorget; vektorfilerna läses in som datamängder, övriga sparas på datorn. Nyckeln sparas aldrig i klartext.\",\n \"docs\": \"https://www.lantmateriet.se/sv/geodata/vara-produkter/oppna-data/\",\n \"level\": 2,\n \"country\": \"SE\",\n \"baseUrl\": \"https://api.lantmateriet.se\",\n \"license\": {\n  \"name\": \"CC BY 4.0\",\n  \"url\": \"https://creativecommons.org/licenses/by/4.0/\"\n },\n \"auth\": {\n  \"type\": \"oauth2_client_credentials\",\n  \"tokenUrl\": \"https://apimanager.lantmateriet.se/oauth2/token\",\n  \"help\": \"Konsumentnyckel (consumer key) och konsumenthemlighet (consumer secret) från Geotorget.\",\n  \"signupUrl\": \"https://geotorget.lantmateriet.se/\"\n },\n \"files\": {\n  \"column\": \"asset_data\",\n  \"hosts\": [\n   \"dl1.lantmateriet.se\"\n  ]\n },\n \"endpoints\": [\n  {\n   \"id\": \"vektor-samlingar\",\n   \"name\": \"Vektordata: samlingar\",\n   \"method\": \"GET\",\n   \"path\": \"/stac-vektor/v1/collections\",\n   \"response\": {\n    \"format\": \"json\",\n    \"path\": \"collections\",\n    \"drop\": [\n     \"links\",\n     \"stac_version\",\n     \"stac_extensions\",\n     \"type\",\n     \"summaries\",\n     \"item_assets\"\n    ]\n   },\n   \"dataset\": {\n    \"name\": \"Lantmäteriet vektordata: samlingar\"\n   }\n  },\n  {\n   \"id\": \"vektor\",\n   \"name\": \"Vektordata: sök filer\",\n   \"description\": \"Filerna i en samling inom ett område, med sina ytor som karta och adresserna till filerna. Kortet Filer i källan i Hantera hämtar dem med nyckeln.\",\n   \"method\": \"GET\",\n   \"path\": \"/stac-vektor/v1/search\",\n   \"params\": [\n    {\n     \"name\": \"collections\",\n     \"in\": \"query\",\n     \"label\": \"Samling\",\n     \"type\": \"string\",\n     \"required\": true,\n     \"optionsFrom\": {\n      \"endpoint\": \"vektor-samlingar\",\n      \"value\": \"id\",\n      \"label\": \"title\"\n     }\n    },\n    {\n     \"name\": \"bbox\",\n     \"in\": \"query\",\n     \"type\": \"string\",\n     \"label\": \"Område (bbox)\",\n     \"help\": \"Västlig longitud, sydlig latitud, östlig longitud, nordlig latitud i WGS 84, avdelade med komma. Tomt = hela tjänsten.\",\n     \"example\": \"17.95,59.30,18.10,59.36\"\n    },\n    {\n     \"name\": \"limit\",\n     \"in\": \"query\",\n     \"type\": \"number\",\n     \"default\": 100,\n     \"hidden\": true\n    }\n   ],\n   \"pagination\": {\n    \"type\": \"link-rel\",\n    \"path\": \"links\",\n    \"rel\": \"next\",\n    \"maxPages\": 50\n   },\n   \"response\": {\n    \"format\": \"geojson\"\n   },\n   \"dataset\": {\n    \"name\": \"Lantmäteriet {collections}\"\n   }\n  },\n  {\n   \"id\": \"bild-samlingar\",\n   \"name\": \"Ortofoton: samlingar\",\n   \"method\": \"GET\",\n   \"path\": \"/stac-bild/v1/collections\",\n   \"response\": {\n    \"format\": \"json\",\n    \"path\": \"collections\",\n    \"drop\": [\n     \"links\",\n     \"stac_version\",\n     \"stac_extensions\",\n     \"type\",\n     \"summaries\",\n     \"item_assets\"\n    ]\n   },\n   \"dataset\": {\n    \"name\": \"Lantmäteriet ortofoton: samlingar\"\n   }\n  },\n  {\n   \"id\": \"bild\",\n   \"name\": \"Ortofoton: sök filer\",\n   \"description\": \"Filerna i en samling inom ett område, med sina ytor som karta och adresserna till filerna. Kortet Filer i källan i Hantera hämtar dem med nyckeln.\",\n   \"method\": \"GET\",\n   \"path\": \"/stac-bild/v1/search\",\n   \"params\": [\n    {\n     \"name\": \"collections\",\n     \"in\": \"query\",\n     \"label\": \"Samling\",\n     \"type\": \"string\",\n     \"required\": true,\n     \"optionsFrom\": {\n      \"endpoint\": \"bild-samlingar\",\n      \"value\": \"id\",\n      \"label\": \"title\"\n     }\n    },\n    {\n     \"name\": \"bbox\",\n     \"in\": \"query\",\n     \"type\": \"string\",\n     \"label\": \"Område (bbox)\",\n     \"help\": \"Västlig longitud, sydlig latitud, östlig longitud, nordlig latitud i WGS 84, avdelade med komma. Tomt = hela tjänsten.\",\n     \"example\": \"17.95,59.30,18.10,59.36\"\n    },\n    {\n     \"name\": \"limit\",\n     \"in\": \"query\",\n     \"type\": \"number\",\n     \"default\": 100,\n     \"hidden\": true\n    }\n   ],\n   \"pagination\": {\n    \"type\": \"link-rel\",\n    \"path\": \"links\",\n    \"rel\": \"next\",\n    \"maxPages\": 50\n   },\n   \"response\": {\n    \"format\": \"geojson\"\n   },\n   \"dataset\": {\n    \"name\": \"Lantmäteriet {collections}\"\n   }\n  },\n  {\n   \"id\": \"hojd-samlingar\",\n   \"name\": \"Höjddata: samlingar\",\n   \"method\": \"GET\",\n   \"path\": \"/stac-hojd/v1/collections\",\n   \"response\": {\n    \"format\": \"json\",\n    \"path\": \"collections\",\n    \"drop\": [\n     \"links\",\n     \"stac_version\",\n     \"stac_extensions\",\n     \"type\",\n     \"summaries\",\n     \"item_assets\"\n    ]\n   },\n   \"dataset\": {\n    \"name\": \"Lantmäteriet höjddata: samlingar\"\n   }\n  },\n  {\n   \"id\": \"hojd\",\n   \"name\": \"Höjddata: sök filer\",\n   \"description\": \"Filerna i en samling inom ett område, med sina ytor som karta och adresserna till filerna. Kortet Filer i källan i Hantera hämtar dem med nyckeln.\",\n   \"method\": \"GET\",\n   \"path\": \"/stac-hojd/v1/search\",\n   \"params\": [\n    {\n     \"name\": \"collections\",\n     \"in\": \"query\",\n     \"label\": \"Samling\",\n     \"type\": \"string\",\n     \"required\": true,\n     \"optionsFrom\": {\n      \"endpoint\": \"hojd-samlingar\",\n      \"value\": \"id\",\n      \"label\": \"title\"\n     }\n    },\n    {\n     \"name\": \"bbox\",\n     \"in\": \"query\",\n     \"type\": \"string\",\n     \"label\": \"Område (bbox)\",\n     \"help\": \"Västlig longitud, sydlig latitud, östlig longitud, nordlig latitud i WGS 84, avdelade med komma. Tomt = hela tjänsten.\",\n     \"example\": \"17.95,59.30,18.10,59.36\"\n    },\n    {\n     \"name\": \"limit\",\n     \"in\": \"query\",\n     \"type\": \"number\",\n     \"default\": 100,\n     \"hidden\": true\n    }\n   ],\n   \"pagination\": {\n    \"type\": \"link-rel\",\n    \"path\": \"links\",\n    \"rel\": \"next\",\n    \"maxPages\": 50\n   },\n   \"response\": {\n    \"format\": \"geojson\"\n   },\n   \"dataset\": {\n    \"name\": \"Lantmäteriet {collections}\"\n   }\n  },\n  {\n   \"id\": \"karta-samlingar\",\n   \"name\": \"Kartor: samlingar\",\n   \"method\": \"GET\",\n   \"path\": \"/stac-karta/v1/collections\",\n   \"response\": {\n    \"format\": \"json\",\n    \"path\": \"collections\",\n    \"drop\": [\n     \"links\",\n     \"stac_version\",\n     \"stac_extensions\",\n     \"type\",\n     \"summaries\",\n     \"item_assets\"\n    ]\n   },\n   \"dataset\": {\n    \"name\": \"Lantmäteriet kartor: samlingar\"\n   }\n  },\n  {\n   \"id\": \"karta\",\n   \"name\": \"Kartor: sök filer\",\n   \"description\": \"Filerna i en samling inom ett område, med sina ytor som karta och adresserna till filerna. Kortet Filer i källan i Hantera hämtar dem med nyckeln.\",\n   \"method\": \"GET\",\n   \"path\": \"/stac-karta/v1/search\",\n   \"params\": [\n    {\n     \"name\": \"collections\",\n     \"in\": \"query\",\n     \"label\": \"Samling\",\n     \"type\": \"string\",\n     \"required\": true,\n     \"optionsFrom\": {\n      \"endpoint\": \"karta-samlingar\",\n      \"value\": \"id\",\n      \"label\": \"title\"\n     }\n    },\n    {\n     \"name\": \"bbox\",\n     \"in\": \"query\",\n     \"type\": \"string\",\n     \"label\": \"Område (bbox)\",\n     \"help\": \"Västlig longitud, sydlig latitud, östlig longitud, nordlig latitud i WGS 84, avdelade med komma. Tomt = hela tjänsten.\",\n     \"example\": \"17.95,59.30,18.10,59.36\"\n    },\n    {\n     \"name\": \"limit\",\n     \"in\": \"query\",\n     \"type\": \"number\",\n     \"default\": 100,\n     \"hidden\": true\n    }\n   ],\n   \"pagination\": {\n    \"type\": \"link-rel\",\n    \"path\": \"links\",\n    \"rel\": \"next\",\n    \"maxPages\": 50\n   },\n   \"response\": {\n    \"format\": \"geojson\"\n   },\n   \"dataset\": {\n    \"name\": \"Lantmäteriet {collections}\"\n   }\n  }\n ],\n \"notes\": \"Kräver en konsumentnyckel och konsumenthemlighet från ett kostnadsfritt konto i Geotorget; appen hämtar en åtkomsttoken med dem. Sökningen svarar i sidor om 100 filer med ytorna i WGS 84. Filerna hämtas från dl1.lantmateriet.se, den enda värd som får nyckeln. CC BY 4.0 enligt katalogen.\",\n \"i18n\": {\n  \"en\": {\n   \"name\": \"Lantmäteriet geodata with a key (STAC)\",\n   \"description\": \"Lantmäteriet’s four STAC catalogues: vector data (buildings, land cover, place names, property division, addresses), orthophotos, elevation data (the terrain model and laser data) and maps. Search files within an area and fetch them with the key from Geotorget; the vector files are read in as datasets, the others are saved on the computer. The key is never stored in clear text.\",\n   \"notes\": \"Requires a consumer key and consumer secret from a free account in Geotorget; the app fetches an access token with them. The search answers in pages of 100 files with their footprints in WGS 84. The files are fetched from dl1.lantmateriet.se, the only host that gets the key. CC BY 4.0 according to the catalogue.\",\n   \"auth\": {\n    \"help\": \"Consumer key and consumer secret from Geotorget.\"\n   },\n   \"endpoints\": {\n    \"vektor-samlingar\": {\n     \"name\": \"Vector data: collections\"\n    },\n    \"vektor\": {\n     \"name\": \"Vector data: search files\",\n     \"description\": \"The files of a collection within an area, with their footprints as a map and the addresses of the files. The card Files in the source in Manage fetches them with the key.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Collection\"\n      },\n      \"bbox\": {\n       \"label\": \"Area (bbox)\",\n       \"help\": \"West longitude, south latitude, east longitude, north latitude in WGS 84, separated by commas. Empty = the whole service.\"\n      }\n     }\n    },\n    \"bild-samlingar\": {\n     \"name\": \"Orthophotos: collections\"\n    },\n    \"bild\": {\n     \"name\": \"Orthophotos: search files\",\n     \"description\": \"The files of a collection within an area, with their footprints as a map and the addresses of the files. The card Files in the source in Manage fetches them with the key.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Collection\"\n      },\n      \"bbox\": {\n       \"label\": \"Area (bbox)\",\n       \"help\": \"West longitude, south latitude, east longitude, north latitude in WGS 84, separated by commas. Empty = the whole service.\"\n      }\n     }\n    },\n    \"hojd-samlingar\": {\n     \"name\": \"Elevation data: collections\"\n    },\n    \"hojd\": {\n     \"name\": \"Elevation data: search files\",\n     \"description\": \"The files of a collection within an area, with their footprints as a map and the addresses of the files. The card Files in the source in Manage fetches them with the key.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Collection\"\n      },\n      \"bbox\": {\n       \"label\": \"Area (bbox)\",\n       \"help\": \"West longitude, south latitude, east longitude, north latitude in WGS 84, separated by commas. Empty = the whole service.\"\n      }\n     }\n    },\n    \"karta-samlingar\": {\n     \"name\": \"Maps: collections\"\n    },\n    \"karta\": {\n     \"name\": \"Maps: search files\",\n     \"description\": \"The files of a collection within an area, with their footprints as a map and the addresses of the files. The card Files in the source in Manage fetches them with the key.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Collection\"\n      },\n      \"bbox\": {\n       \"label\": \"Area (bbox)\",\n       \"help\": \"West longitude, south latitude, east longitude, north latitude in WGS 84, separated by commas. Empty = the whole service.\"\n      }\n     }\n    }\n   }\n  },\n  \"da\": {\n   \"name\": \"Lantmäteriet geodata med nøgle (STAC)\",\n   \"description\": \"Lantmäteriets fire STAC-kataloger: vektordata (bygninger, arealdække, stednavne, matrikelinddeling, adresser), ortofotos, højdedata (terrænmodellen og laserdata) og kort. Søg filer inden for et område, og hent dem med nøglen fra Geotorget; vektorfilerne indlæses som datasæt, de øvrige gemmes på computeren. Nøglen gemmes aldrig i klartekst.\",\n   \"notes\": \"Kræver en forbrugernøgle og forbrugerhemmelighed fra en gratis konto i Geotorget; appen henter et adgangstoken med dem. Søgningen svarer i sider på 100 filer med fladerne i WGS 84. Filerne hentes fra dl1.lantmateriet.se, den eneste vært, der får nøglen. CC BY 4.0 ifølge kataloget.\",\n   \"auth\": {\n    \"help\": \"Forbrugernøgle (consumer key) og forbrugerhemmelighed (consumer secret) fra Geotorget.\"\n   },\n   \"endpoints\": {\n    \"vektor-samlingar\": {\n     \"name\": \"Vektordata: samlinger\"\n    },\n    \"vektor\": {\n     \"name\": \"Vektordata: søg filer\",\n     \"description\": \"Filerne i en samling inden for et område, med deres flader som kort og adresserne til filerne. Kortet Filer i kilden i Håndter henter dem med nøglen.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Samling\"\n      },\n      \"bbox\": {\n       \"label\": \"Område (bbox)\",\n       \"help\": \"Vestlig længdegrad, sydlig breddegrad, østlig længdegrad, nordlig breddegrad i WGS 84, adskilt med komma. Tomt = hele tjenesten.\"\n      }\n     }\n    },\n    \"bild-samlingar\": {\n     \"name\": \"Ortofotos: samlinger\"\n    },\n    \"bild\": {\n     \"name\": \"Ortofotos: søg filer\",\n     \"description\": \"Filerne i en samling inden for et område, med deres flader som kort og adresserne til filerne. Kortet Filer i kilden i Håndter henter dem med nøglen.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Samling\"\n      },\n      \"bbox\": {\n       \"label\": \"Område (bbox)\",\n       \"help\": \"Vestlig længdegrad, sydlig breddegrad, østlig længdegrad, nordlig breddegrad i WGS 84, adskilt med komma. Tomt = hele tjenesten.\"\n      }\n     }\n    },\n    \"hojd-samlingar\": {\n     \"name\": \"Højdedata: samlinger\"\n    },\n    \"hojd\": {\n     \"name\": \"Højdedata: søg filer\",\n     \"description\": \"Filerne i en samling inden for et område, med deres flader som kort og adresserne til filerne. Kortet Filer i kilden i Håndter henter dem med nøglen.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Samling\"\n      },\n      \"bbox\": {\n       \"label\": \"Område (bbox)\",\n       \"help\": \"Vestlig længdegrad, sydlig breddegrad, østlig længdegrad, nordlig breddegrad i WGS 84, adskilt med komma. Tomt = hele tjenesten.\"\n      }\n     }\n    },\n    \"karta-samlingar\": {\n     \"name\": \"Kort: samlinger\"\n    },\n    \"karta\": {\n     \"name\": \"Kort: søg filer\",\n     \"description\": \"Filerne i en samling inden for et område, med deres flader som kort og adresserne til filerne. Kortet Filer i kilden i Håndter henter dem med nøglen.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Samling\"\n      },\n      \"bbox\": {\n       \"label\": \"Område (bbox)\",\n       \"help\": \"Vestlig længdegrad, sydlig breddegrad, østlig længdegrad, nordlig breddegrad i WGS 84, adskilt med komma. Tomt = hele tjenesten.\"\n      }\n     }\n    }\n   }\n  },\n  \"nb\": {\n   \"name\": \"Lantmäteriet geodata med nøkkel (STAC)\",\n   \"description\": \"Lantmäteriets fire STAC-kataloger: vektordata (bygninger, arealdekke, stedsnavn, eiendomsinndeling, adresser), ortofoto, høydedata (terrengmodellen og laserdata) og kart. Søk filer innenfor et område og hent dem med nøkkelen fra Geotorget; vektorfilene leses inn som datasett, de øvrige lagres på datamaskinen. Nøkkelen lagres aldri i klartekst.\",\n   \"notes\": \"Krever en forbrukernøkkel og forbrukerhemmelighet fra en gratis konto i Geotorget; appen henter et tilgangstoken med dem. Søket svarer i sider på 100 filer med flatene i WGS 84. Filene hentes fra dl1.lantmateriet.se, den eneste verten som får nøkkelen. CC BY 4.0 ifølge katalogen.\",\n   \"auth\": {\n    \"help\": \"Forbrukernøkkel (consumer key) og forbrukerhemmelighet (consumer secret) fra Geotorget.\"\n   },\n   \"endpoints\": {\n    \"vektor-samlingar\": {\n     \"name\": \"Vektordata: samlinger\"\n    },\n    \"vektor\": {\n     \"name\": \"Vektordata: søk filer\",\n     \"description\": \"Filene i en samling innenfor et område, med flatene som kart og adressene til filene. Kortet Filer i kilden i Håndter henter dem med nøkkelen.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Samling\"\n      },\n      \"bbox\": {\n       \"label\": \"Område (bbox)\",\n       \"help\": \"Vestlig lengdegrad, sørlig breddegrad, østlig lengdegrad, nordlig breddegrad i WGS 84, skilt med komma. Tomt = hele tjenesten.\"\n      }\n     }\n    },\n    \"bild-samlingar\": {\n     \"name\": \"Ortofoto: samlinger\"\n    },\n    \"bild\": {\n     \"name\": \"Ortofoto: søk filer\",\n     \"description\": \"Filene i en samling innenfor et område, med flatene som kart og adressene til filene. Kortet Filer i kilden i Håndter henter dem med nøkkelen.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Samling\"\n      },\n      \"bbox\": {\n       \"label\": \"Område (bbox)\",\n       \"help\": \"Vestlig lengdegrad, sørlig breddegrad, østlig lengdegrad, nordlig breddegrad i WGS 84, skilt med komma. Tomt = hele tjenesten.\"\n      }\n     }\n    },\n    \"hojd-samlingar\": {\n     \"name\": \"Høydedata: samlinger\"\n    },\n    \"hojd\": {\n     \"name\": \"Høydedata: søk filer\",\n     \"description\": \"Filene i en samling innenfor et område, med flatene som kart og adressene til filene. Kortet Filer i kilden i Håndter henter dem med nøkkelen.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Samling\"\n      },\n      \"bbox\": {\n       \"label\": \"Område (bbox)\",\n       \"help\": \"Vestlig lengdegrad, sørlig breddegrad, østlig lengdegrad, nordlig breddegrad i WGS 84, skilt med komma. Tomt = hele tjenesten.\"\n      }\n     }\n    },\n    \"karta-samlingar\": {\n     \"name\": \"Kart: samlinger\"\n    },\n    \"karta\": {\n     \"name\": \"Kart: søk filer\",\n     \"description\": \"Filene i en samling innenfor et område, med flatene som kart og adressene til filene. Kortet Filer i kilden i Håndter henter dem med nøkkelen.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Samling\"\n      },\n      \"bbox\": {\n       \"label\": \"Område (bbox)\",\n       \"help\": \"Vestlig lengdegrad, sørlig breddegrad, østlig lengdegrad, nordlig breddegrad i WGS 84, skilt med komma. Tomt = hele tjenesten.\"\n      }\n     }\n    }\n   }\n  },\n  \"nn\": {\n   \"name\": \"Lantmäteriet geodata med nøkkel (STAC)\",\n   \"description\": \"Dei fire STAC-katalogane til Lantmäteriet: vektordata (bygningar, arealdekke, stadnamn, eigedomsinndeling, adresser), ortofoto, høgdedata (terrengmodellen og laserdata) og kart. Søk filer innanfor eit område og hent dei med nøkkelen frå Geotorget; vektorfilene blir lesne inn som datasett, dei andre blir lagra på datamaskina. Nøkkelen blir aldri lagra i klartekst.\",\n   \"notes\": \"Krev ein forbrukarnøkkel og forbrukarløyndom frå ein gratis konto i Geotorget; appen hentar eit tilgangstoken med dei. Søket svarar i sider på 100 filer med flatene i WGS 84. Filene blir henta frå dl1.lantmateriet.se, den einaste verten som får nøkkelen. CC BY 4.0 ifølgje katalogen.\",\n   \"auth\": {\n    \"help\": \"Forbrukarnøkkel (consumer key) og forbrukarløyndom (consumer secret) frå Geotorget.\"\n   },\n   \"endpoints\": {\n    \"vektor-samlingar\": {\n     \"name\": \"Vektordata: samlingar\"\n    },\n    \"vektor\": {\n     \"name\": \"Vektordata: søk filer\",\n     \"description\": \"Filene i ei samling innanfor eit område, med flatene som kart og adressene til filene. Kortet Filer i kjelda i Handter hentar dei med nøkkelen.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Samling\"\n      },\n      \"bbox\": {\n       \"label\": \"Område (bbox)\",\n       \"help\": \"Vestleg lengdegrad, sørleg breiddegrad, austleg lengdegrad, nordleg breiddegrad i WGS 84, skilde med komma. Tomt = heile tenesta.\"\n      }\n     }\n    },\n    \"bild-samlingar\": {\n     \"name\": \"Ortofoto: samlingar\"\n    },\n    \"bild\": {\n     \"name\": \"Ortofoto: søk filer\",\n     \"description\": \"Filene i ei samling innanfor eit område, med flatene som kart og adressene til filene. Kortet Filer i kjelda i Handter hentar dei med nøkkelen.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Samling\"\n      },\n      \"bbox\": {\n       \"label\": \"Område (bbox)\",\n       \"help\": \"Vestleg lengdegrad, sørleg breiddegrad, austleg lengdegrad, nordleg breiddegrad i WGS 84, skilde med komma. Tomt = heile tenesta.\"\n      }\n     }\n    },\n    \"hojd-samlingar\": {\n     \"name\": \"Høgdedata: samlingar\"\n    },\n    \"hojd\": {\n     \"name\": \"Høgdedata: søk filer\",\n     \"description\": \"Filene i ei samling innanfor eit område, med flatene som kart og adressene til filene. Kortet Filer i kjelda i Handter hentar dei med nøkkelen.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Samling\"\n      },\n      \"bbox\": {\n       \"label\": \"Område (bbox)\",\n       \"help\": \"Vestleg lengdegrad, sørleg breiddegrad, austleg lengdegrad, nordleg breiddegrad i WGS 84, skilde med komma. Tomt = heile tenesta.\"\n      }\n     }\n    },\n    \"karta-samlingar\": {\n     \"name\": \"Kart: samlingar\"\n    },\n    \"karta\": {\n     \"name\": \"Kart: søk filer\",\n     \"description\": \"Filene i ei samling innanfor eit område, med flatene som kart og adressene til filene. Kortet Filer i kjelda i Handter hentar dei med nøkkelen.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Samling\"\n      },\n      \"bbox\": {\n       \"label\": \"Område (bbox)\",\n       \"help\": \"Vestleg lengdegrad, sørleg breiddegrad, austleg lengdegrad, nordleg breiddegrad i WGS 84, skilde med komma. Tomt = heile tenesta.\"\n      }\n     }\n    }\n   }\n  },\n  \"fi\": {\n   \"name\": \"Lantmäteriet paikkatiedot avaimella (STAC)\",\n   \"description\": \"Lantmäterietin neljä STAC-luetteloa: vektoriaineistot (rakennukset, maanpeite, paikannimet, kiinteistöjaotus, osoitteet), ortoilmakuvat, korkeusaineistot (maastomalli ja laseraineisto) ja kartat. Hae tiedostoja alueelta ja nouda ne Geotorgetin avaimella; vektoritiedostot luetaan aineistoiksi, muut tallennetaan tietokoneelle. Avainta ei koskaan tallenneta selväkielisenä.\",\n   \"notes\": \"Vaatii kuluttaja-avaimen ja kuluttajasalaisuuden maksuttomalta Geotorget-tililtä; sovellus hakee niillä käyttötunnisteen. Haku vastaa 100 tiedoston sivuina, alueet WGS 84 -järjestelmässä. Tiedostot haetaan osoitteesta dl1.lantmateriet.se, joka on ainoa avaimen saava palvelin. CC BY 4.0 luettelon mukaan.\",\n   \"auth\": {\n    \"help\": \"Kuluttaja-avain (consumer key) ja kuluttajasalaisuus (consumer secret) Geotorgetista.\"\n   },\n   \"endpoints\": {\n    \"vektor-samlingar\": {\n     \"name\": \"Vektoriaineistot: kokoelmat\"\n    },\n    \"vektor\": {\n     \"name\": \"Vektoriaineistot: hae tiedostoja\",\n     \"description\": \"Kokoelman tiedostot alueella, niiden alueet karttana ja tiedostojen osoitteet. Hallitse-tilan kortti Lähteen tiedostot hakee ne avaimella.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Kokoelma\"\n      },\n      \"bbox\": {\n       \"label\": \"Alue (bbox)\",\n       \"help\": \"Läntinen pituusaste, eteläinen leveysaste, itäinen pituusaste, pohjoinen leveysaste WGS 84:ssä pilkuilla erotettuina. Tyhjä = koko palvelu.\"\n      }\n     }\n    },\n    \"bild-samlingar\": {\n     \"name\": \"Ortoilmakuvat: kokoelmat\"\n    },\n    \"bild\": {\n     \"name\": \"Ortoilmakuvat: hae tiedostoja\",\n     \"description\": \"Kokoelman tiedostot alueella, niiden alueet karttana ja tiedostojen osoitteet. Hallitse-tilan kortti Lähteen tiedostot hakee ne avaimella.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Kokoelma\"\n      },\n      \"bbox\": {\n       \"label\": \"Alue (bbox)\",\n       \"help\": \"Läntinen pituusaste, eteläinen leveysaste, itäinen pituusaste, pohjoinen leveysaste WGS 84:ssä pilkuilla erotettuina. Tyhjä = koko palvelu.\"\n      }\n     }\n    },\n    \"hojd-samlingar\": {\n     \"name\": \"Korkeusaineistot: kokoelmat\"\n    },\n    \"hojd\": {\n     \"name\": \"Korkeusaineistot: hae tiedostoja\",\n     \"description\": \"Kokoelman tiedostot alueella, niiden alueet karttana ja tiedostojen osoitteet. Hallitse-tilan kortti Lähteen tiedostot hakee ne avaimella.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Kokoelma\"\n      },\n      \"bbox\": {\n       \"label\": \"Alue (bbox)\",\n       \"help\": \"Läntinen pituusaste, eteläinen leveysaste, itäinen pituusaste, pohjoinen leveysaste WGS 84:ssä pilkuilla erotettuina. Tyhjä = koko palvelu.\"\n      }\n     }\n    },\n    \"karta-samlingar\": {\n     \"name\": \"Kartat: kokoelmat\"\n    },\n    \"karta\": {\n     \"name\": \"Kartat: hae tiedostoja\",\n     \"description\": \"Kokoelman tiedostot alueella, niiden alueet karttana ja tiedostojen osoitteet. Hallitse-tilan kortti Lähteen tiedostot hakee ne avaimella.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Kokoelma\"\n      },\n      \"bbox\": {\n       \"label\": \"Alue (bbox)\",\n       \"help\": \"Läntinen pituusaste, eteläinen leveysaste, itäinen pituusaste, pohjoinen leveysaste WGS 84:ssä pilkuilla erotettuina. Tyhjä = koko palvelu.\"\n      }\n     }\n    }\n   }\n  },\n  \"is\": {\n   \"name\": \"Landupplýsingar Lantmäteriet með lykli (STAC)\",\n   \"description\": \"Fjórar STAC-skrár Lantmäteriet: vigurgögn (byggingar, landþekja, örnefni, fasteignaskipting, heimilisföng), réttmyndir, hæðargögn (landlíkanið og leysigögn) og kort. Leitaðu að skrám innan svæðis og sæktu þær með lyklinum frá Geotorget; vigurskrárnar eru lesnar inn sem gagnasöfn, hinar vistaðar á tölvunni. Lykillinn er aldrei vistaður í hreinum texta.\",\n   \"notes\": \"Krefst neytendalykils og neytendaleyndarmáls af ókeypis aðgangi í Geotorget; forritið sækir aðgangstákn með þeim. Leitin svarar í síðum með 100 skrám með fleti í WGS 84. Skrárnar eru sóttar frá dl1.lantmateriet.se, eina hýsilinum sem fær lykilinn. CC BY 4.0 samkvæmt skránni.\",\n   \"auth\": {\n    \"help\": \"Neytendalykill (consumer key) og neytendaleyndarmál (consumer secret) frá Geotorget.\"\n   },\n   \"endpoints\": {\n    \"vektor-samlingar\": {\n     \"name\": \"Vigurgögn: söfn\"\n    },\n    \"vektor\": {\n     \"name\": \"Vigurgögn: leita að skrám\",\n     \"description\": \"Skrár safns innan svæðis, með fleti sína sem kort og vistföng skránna. Spjaldið Skrár í uppsprettunni í Umsjón sækir þær með lyklinum.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Safn\"\n      },\n      \"bbox\": {\n       \"label\": \"Svæði (bbox)\",\n       \"help\": \"Vestlæg lengd, suðlæg breidd, austlæg lengd, norðlæg breidd í WGS 84, aðskilin með kommu. Tómt = öll þjónustan.\"\n      }\n     }\n    },\n    \"bild-samlingar\": {\n     \"name\": \"Réttmyndir: söfn\"\n    },\n    \"bild\": {\n     \"name\": \"Réttmyndir: leita að skrám\",\n     \"description\": \"Skrár safns innan svæðis, með fleti sína sem kort og vistföng skránna. Spjaldið Skrár í uppsprettunni í Umsjón sækir þær með lyklinum.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Safn\"\n      },\n      \"bbox\": {\n       \"label\": \"Svæði (bbox)\",\n       \"help\": \"Vestlæg lengd, suðlæg breidd, austlæg lengd, norðlæg breidd í WGS 84, aðskilin með kommu. Tómt = öll þjónustan.\"\n      }\n     }\n    },\n    \"hojd-samlingar\": {\n     \"name\": \"Hæðargögn: söfn\"\n    },\n    \"hojd\": {\n     \"name\": \"Hæðargögn: leita að skrám\",\n     \"description\": \"Skrár safns innan svæðis, með fleti sína sem kort og vistföng skránna. Spjaldið Skrár í uppsprettunni í Umsjón sækir þær með lyklinum.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Safn\"\n      },\n      \"bbox\": {\n       \"label\": \"Svæði (bbox)\",\n       \"help\": \"Vestlæg lengd, suðlæg breidd, austlæg lengd, norðlæg breidd í WGS 84, aðskilin með kommu. Tómt = öll þjónustan.\"\n      }\n     }\n    },\n    \"karta-samlingar\": {\n     \"name\": \"Kort: söfn\"\n    },\n    \"karta\": {\n     \"name\": \"Kort: leita að skrám\",\n     \"description\": \"Skrár safns innan svæðis, með fleti sína sem kort og vistföng skránna. Spjaldið Skrár í uppsprettunni í Umsjón sækir þær með lyklinum.\",\n     \"params\": {\n      \"collections\": {\n       \"label\": \"Safn\"\n      },\n      \"bbox\": {\n       \"label\": \"Svæði (bbox)\",\n       \"help\": \"Vestlæg lengd, suðlæg breidd, austlæg lengd, norðlæg breidd í WGS 84, aðskilin með kommu. Tómt = öll þjónustan.\"\n      }\n     }\n    }\n   }\n  }\n }\n}\n");
